import{_ as t,o,c as i,ae as n}from"./chunks/framework.DPZ3sAUK.js";const h=JSON.parse('{"title":"neuron-js: Pluggable Execution Runtime","description":"","frontmatter":{},"headers":[],"relativePath":"overview.md","filePath":"overview.md"}'),a={name:"overview.md"};function r(s,e,l,c,u,d){return o(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="neuron-js-pluggable-execution-runtime" tabindex="-1">neuron-js: Pluggable Execution Runtime <a class="header-anchor" href="#neuron-js-pluggable-execution-runtime" aria-label="Permalink to &quot;neuron-js: Pluggable Execution Runtime&quot;">​</a></h1><p><code>neuron-js</code> is a lightweight, extensible, and JSON-serializable execution engine for JavaScript. It allows developers to define complex logic flows (functional scripts) that can be stored in a database, transmitted over the wire, and executed consistently in both Node.js and browser environments.</p><h2 id="the-problem" tabindex="-1">The Problem <a class="header-anchor" href="#the-problem" aria-label="Permalink to &quot;The Problem&quot;">​</a></h2><p>Hardcoding business logic often leads to rigid systems that are difficult to update without a full deployment. Workflow engines are often heavy, difficult to integrate, or use proprietary formats.</p><h2 id="the-solution" tabindex="-1">The Solution <a class="header-anchor" href="#the-solution" aria-label="Permalink to &quot;The Solution&quot;">​</a></h2><p><code>neuron-js</code> provides a &quot;biological&quot; approach to execution logic:</p><ul><li><strong>Neurons</strong> store the definitions of what is possible (Actions, Conditions).</li><li><strong>Synapses</strong> execute specific scripts by connecting these neurons together in a logical flow.</li></ul><p>By keeping the script format strictly serializable (JSON), <code>neuron-js</code> enables:</p><ul><li><strong>Dynamic Logic</strong>: Change business rules at runtime without redeploying code.</li><li><strong>Portability</strong>: The same logic can run on a backend server or in a client&#39;s browser.</li><li><strong>Extensibility</strong>: Easily add new capabilities by implementing simple Action or Condition interfaces.</li></ul><h2 id="key-features" tabindex="-1">Key Features <a class="header-anchor" href="#key-features" aria-label="Permalink to &quot;Key Features&quot;">​</a></h2><ul><li><strong>JSON Serializable</strong>: Logic is data.</li><li><strong>Shared Context</strong>: State is managed and passed through the execution chain.</li><li><strong>Logical Grouping</strong>: Complex AND/OR condition logic is supported out of the box.</li><li><strong>Lifecycle Hooks</strong>: Monitor and react to every step of the execution.</li><li><strong>Type Safe</strong>: Built with TypeScript for a robust developer experience.</li></ul>',11)])])}const p=t(a,[["render",r]]);export{h as __pageData,p as default};
